"""The legal team's decisions on findings, and what the system does with them.

Three effects, all visible in the report: (1) the same file checked again gets the earlier decisions carried
over; (2) notes become precedents for the AI cross-check of the same kind of finding; (3) a class of finding the
team has agreed with often enough is accepted automatically, with a deterministic spot-check sample and at least
one spot check per contract - the review rules (thresholds) are the ones in app/policy.py.
"""

import hashlib
from datetime import datetime, timezone

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models import Decision, Document
from app.policy import review_rate

HUMAN = ("accepted", "dismissed")
AS_POLICY = {"accepted": "approved", "dismissed": "rejected"}


def class_key(kind: str, contract_type: str, clause_type: str = "") -> str:
    return "rename" if kind == "old_name" else f"missing:{contract_type}:{clause_type}"


def current_decisions(session: Session, key: str) -> list[Decision]:
    """Latest decision per (file, item), oldest first; reopened items drop out."""
    latest: dict[tuple[str, str], Decision] = {}
    for d in session.scalars(select(Decision).where(Decision.class_key == key).order_by(Decision.id)):
        latest[(d.sha256, d.item_key)] = d
    return sorted((d for d in latest.values() if d.decision in HUMAN), key=lambda d: d.id)


def rate(session: Session, key: str) -> float:
    return review_rate([AS_POLICY[d.decision] for d in current_decisions(session, key)])


def precedents(session: Session, key: str, limit: int = 3) -> list[dict]:
    rows = [d for d in reversed(current_decisions(session, key)) if d.note.strip()][:limit]
    return [{"decision": AS_POLICY[d.decision], "note": d.note, "quote": d.quote} for d in rows]


def previous(session: Session, sha256: str, item_key: str) -> Decision | None:
    d = session.scalar(select(Decision).where(Decision.sha256 == sha256, Decision.item_key == item_key)
                       .order_by(Decision.id.desc()).limit(1))
    return d if d is not None and d.decision in HUMAN else None


def _spot(sha256: str, key: str, r: float) -> bool:
    return int(hashlib.sha256(f"{sha256}:{key}".encode()).hexdigest()[:8], 16) % 100 < round(r * 100)


def apply(session: Session, doc: Document, items: list[dict]) -> None:
    """Fill item['review'] and item['policy'] for every finding of a fresh report."""
    now = datetime.now(timezone.utc).isoformat()
    automated, spot_checked = [], 0
    for it in items:
        prev = previous(session, doc.sha256, it["key"])
        if prev is not None:
            it["review"] = {"status": prev.decision, "note": prev.note, "edited_text": prev.edited_text, "carried_over": True,
                            "decided_at": prev.created_at.isoformat() if prev.created_at else None, "actor": prev.actor}
            it["policy"] = {"kind": "carried_over", "review_rate": rate(session, it["class_key"])}
            continue
        r = rate(session, it["class_key"])
        it["review"] = {"status": "open", "note": "", "edited_text": "", "carried_over": False, "decided_at": None, "actor": ""}
        if not it["verified"] or r >= 1.0:
            it["policy"] = {"kind": "required", "review_rate": r}
        elif _spot(doc.sha256, it["key"], r):
            it["policy"] = {"kind": "spot_check", "review_rate": r}
            spot_checked += 1
        else:
            it["review"].update(status="auto", decided_at=now, actor="system")
            it["policy"] = {"kind": "auto", "review_rate": r}
            automated.append(it)
    if automated and not spot_checked:  # a contract that automates anything still gets one human look
        it = min(automated, key=lambda i: i["key"])
        it["review"].update(status="open", decided_at=None, actor="")
        it["policy"] = {"kind": "spot_check", "review_rate": it["policy"]["review_rate"], "minimum": True}


def record(session: Session, doc: Document, item: dict, decision: str, note: str, edited_text: str, actor: str) -> None:
    session.add(Decision(document_id=doc.id, sha256=doc.sha256, item_key=item["key"], class_key=item["class_key"],
                         decision=decision, note=note, edited_text=edited_text, quote=item.get("quote", "")[:400], actor=actor))
===== api/app/policy.py =====
"""Adaptive human-in-the-loop: the review rate of a finding class falls as the team's decisions prove it right.

Every class starts at full review. Once the legal team has agreed with the system often enough, only a
deterministic spot-check sample is queued and the rest is auto-approved (logged, visible, overturnable).
A single human rejection resets the class to full review. Automation only ever applies to findings the AI
verifier confirmed; "not cross-checked" and "partial" findings always need a person. Earlier decisions on the
same contract are carried over so nobody reviews the same thing twice, and decisions with notes are fed back
to the verifier as precedents.
"""

import hashlib
from datetime import datetime, timezone

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models import Audit, AuditLog, Finding

MIN_DECISIONS = 8  # consecutive agreeing human decisions before any automation (a policy knob; the sample set yields 9)
MIN_AGREEMENT = 0.95  # overall share of approvals required
TIERS = [(24, 0.10), (MIN_DECISIONS, 0.20)]  # (decisions since last rejection, spot-check rate)
HUMAN = ("approved", "rejected")


def class_key(kind: str, params: dict) -> str:
    """What makes findings comparable: the question asked, not the contract."""
    if kind == "missing_clause":
        return f"missing_clause:{params.get('clause_type', '')}"
    if kind == "missing_passage":
        return "missing_passage:" + hashlib.sha1(params.get("passage", "").strip().lower().encode()).hexdigest()[:10]
    return f"rename:{params.get('old_name') or 'registry'}"


def human_decisions(session: Session, key: str) -> list[Finding]:
    return session.scalars(
        select(Finding).where(Finding.class_key == key, Finding.review_status.in_(HUMAN))
        .order_by(Finding.reviewed_at)
    ).all()


def review_rate(decisions: list[str]) -> float:
    """decisions: ordered human decisions ('approved'/'rejected'). Returns the share that still needs a person."""
    if not decisions:
        return 1.0
    agreement = decisions.count("approved") / len(decisions)
    since_rejection = 0
    for d in reversed(decisions):
        if d != "approved":
            break
        since_rejection += 1
    if agreement < MIN_AGREEMENT:
        return 1.0
    for threshold, rate in TIERS:
        if since_rejection >= threshold:
            return rate
    return 1.0


def class_stats(session: Session, key: str) -> dict:
    decisions = [f.review_status for f in human_decisions(session, key)]
    since = 0
    for d in reversed(decisions):
        if d != "approved":
            break
        since += 1
    auto = session.scalar(select(Finding.id).where(Finding.class_key == key, Finding.review_status == "auto_approved").limit(1))
    return {
        "class_key": key,
        "decisions": len(decisions),
        "approved": decisions.count("approved"),
        "rejected": decisions.count("rejected"),
        "since_rejection": since,
        "agreement": round(decisions.count("approved") / len(decisions), 3) if decisions else None,
        "review_rate": review_rate(decisions),
        "automation_active": auto is not None,
    }


def precedents(session: Session, key: str, limit: int = 3) -> list[dict]:
    """The team's most recent decisions with a note, newest first: what they consider acceptable and why."""
    rows = [f for f in reversed(human_decisions(session, key)) if f.review_note.strip()][:limit]
    return [{"decision": f.review_status, "note": f.review_note, "quote": (f.evidence[0]["quote"] if f.evidence else "")}
            for f in rows]


def previous_decision(session: Session, document_id: int, key: str, exclude_id: int | None = None) -> Finding | None:
    """The team's latest decision on the same contract and question, if any."""
    q = select(Finding).where(Finding.document_id == document_id, Finding.class_key == key, Finding.review_status.in_(HUMAN))
    if exclude_id is not None:
        q = q.where(Finding.id != exclude_id)
    return session.scalar(q.order_by(Finding.reviewed_at.desc()).limit(1))


def _spot_check(audit_id: int, sha256: str, rate: float) -> bool:
    """Deterministic sample: reproducible for the audit trail, rotating across runs."""
    return int(hashlib.sha256(f"{audit_id}:{sha256}".encode()).hexdigest()[:8], 16) % 100 < round(rate * 100)


def apply(session: Session, audit: Audit) -> dict:
    """Decide for every new finding whether a person must look at it. Returns counts for the audit summary."""
    key = class_key(audit.kind, audit.params)
    rate = review_rate([f.review_status for f in human_decisions(session, key)])
    counts = {"required": 0, "spot_check": 0, "auto_approved": 0, "carried_over": 0}
    now = datetime.now(timezone.utc)
    for f in audit.findings:
        f.class_key = key
        if f.verdict in ("dismissed", "unreadable"):
            continue
        previous = previous_decision(session, f.document_id, key, exclude_id=f.id)
        if previous is not None:
            counts["carried_over"] += 1
            f.policy = {"kind": "carried_over", "decision": previous.review_status, "note": previous.review_note,
                        "decided_at": previous.reviewed_at.isoformat() if previous.reviewed_at else None,
                        "finding_id": previous.id}
            if previous.review_status == "rejected":
                f.verdict = "dismissed"
                f.method_chain = f.method_chain + [f"carried over: rejected by a reviewer on finding #{previous.id}"]
            else:
                f.review_status, f.review_note, f.reviewed_at = "auto_approved", previous.review_note, now
                f.method_chain = f.method_chain + [f"carried over: approved by a reviewer on finding #{previous.id}"]
                _log(session, f, "finding.auto_approved", {"reason": "carried_over", "from_finding": previous.id})
            continue
        if f.verdict != "confirmed" or rate >= 1.0:
            counts["required"] += 1
            f.policy = {"kind": "required", "reason": "not_verified" if f.verdict != "confirmed" else "learning",
                        "review_rate": rate}
            continue
        if _spot_check(audit.id, f.document.sha256, rate):
            counts["spot_check"] += 1
            f.policy = {"kind": "spot_check", "review_rate": rate}
        else:
            counts["auto_approved"] += 1
            f.review_status, f.reviewed_at = "auto_approved", now
            f.policy = {"kind": "auto", "review_rate": rate}
            f.method_chain = f.method_chain + [f"policy: class review rate {rate:.0%}, auto-approved (AI-confirmed)"]
            _log(session, f, "finding.auto_approved", {"reason": "trusted_class", "class_key": key, "review_rate": rate})
    if counts["auto_approved"] and not counts["spot_check"]:  # every run that automates anything still gets one human look
        f = min((f for f in audit.findings if f.policy.get("kind") == "auto"), key=lambda f: f.document.sha256)
        f.review_status, f.reviewed_at, f.policy = "pending", None, {"kind": "spot_check", "review_rate": rate, "minimum": True}
        f.method_chain = f.method_chain[:-1] + [f"policy: class review rate {rate:.0%}, selected as the run's minimum spot check"]
        session.query(AuditLog).filter(AuditLog.target_type == "finding", AuditLog.target_id == f.id,
                                       AuditLog.action == "finding.auto_approved").delete()
        counts["auto_approved"] -= 1
        counts["spot_check"] += 1
    session.commit()
    return counts


def _log(session: Session, f: Finding, action: str, details: dict) -> None:
    session.add(AuditLog(actor="system", action=action, target_type="finding", target_id=f.id,
                         details={"document_id": f.document_id, "sha256": f.document.sha256, **details}))
